import 'package:pulumi/pulumi.dart';
import 'tenant_args2.dart';

/// Creates a new tenant entity.
class Tenant2 extends CustomResource {
  /// Client side tenant identifier, used to uniquely identify the tenant. The maximum number of allowed characters is 255.
  late final Output<String> externalId;

  /// Required during tenant update. The resource name for a tenant. This is generated by the service when a tenant is created. The format is "projects/{project_id}/tenants/{tenant_id}", for example, "projects/foo/tenants/bar".
  late final Output<String> name;
  late final Output<String> project;

  Tenant2(
    String name, {
    TenantArgs2? args,
    CustomResourceOptions? options,
  }) : super(
          'google-native:jobs/v4:Tenant',
          name,
          Input.mapToInputs(args?.toMap() ?? const {}),
          options ?? CustomResourceOptions(),
        ) {
    this.externalId = Output.createUnknown<String>();
    this.name = Output.createUnknown<String>();
    this.project = Output.createUnknown<String>();
  }
}
